import json,collections
from pathlib import Path
D=json.loads(Path('/tmp/gpu_trace_events.json').read_text()); g=sorted(D['gpu'],key=lambda e:e['ts']); c=D['cpu']; base=g[0]['ts']; end=max(e['ts']+e['dur'] for e in g)
m=[]; gaps=[]; last=None
for e in g:
 s=e['ts']; t=s+e['dur']
 if not m or s>m[-1][1]:
  if m: gaps.append((m[-1][1],s,last,e))
  m.append([s,t]); last=e
 elif t>m[-1][1]: m[-1][1]=t; last=e
idle=sum(b-a for a,b,_,_ in gaps)
print('TOTAL',{'span_s':(end-base)/1e6,'idle_ms':idle/1000,'idle_pct':100*idle/(end-base),'events':len(g),'base_us':base},flush=True)
print('STREAMS',collections.Counter(e.get('args',{}).get('stream') for e in g))
for lo,hi in [(0,10),(10,50),(50,100),(100,500),(500,1000),(1000,10000),(10000,1e20)]:
 gs=[x for x in gaps if lo<x[1]-x[0]<=hi]; print('BUCKET_US',lo,hi,'COUNT',len(gs),'TOTAL_MS',sum(x[1]-x[0] for x in gs)/1000)
ann=[e for e in c if e.get('cat')=='user_annotation']; runtime=[e for e in c if e.get('cat')=='cuda_runtime']
print('ANNOTATIONS',collections.Counter(e['name'] for e in ann).most_common(30))
for a,b,pr,ne in sorted(gaps,key=lambda x:x[1]-x[0],reverse=True)[:12]:
 print('GAP',round((a-base)/1e6,6),round((b-base)/1e6,6),'US',round(b-a,3),'PREV',pr['name'][:130],'NEXT',ne['name'][:130])
 for group in [ann,runtime]:
  near=[e for e in group if e['ts']<b and e['ts']+e.get('dur',0)>a]
  print('CPU',[(e['name'],round((e['ts']-base)/1e6,6),e['dur']) for e in near[:15]])
for i in range(10):
 a=base+(end-base)*i/10; b=base+(end-base)*(i+1)/10; busy=sum(max(0,min(t,b)-max(s,a)) for s,t in m)
 print('DECILE',i,round((a-base)/1e6,4),round((b-base)/1e6,4),'IDLE_PCT',round(100*(1-busy/(b-a)),3))
# Idle time within each scheduler forward annotation.
for name in sorted(set(e['name'] for e in ann)):
 es=[e for e in ann if e['name']==name]
 if any(x in name.lower() for x in ['forward','prefill','decode','extend']):
  vals=[]
  for e in es:
   a=max(base,e['ts']); b=min(end,e['ts']+e['dur'])
   if b>a:
    busy=sum(max(0,min(t,b)-max(s,a)) for s,t in m); vals.append((b-a,b-a-busy))
  print('PHASE',name,'COUNT',len(es),'SPAN_MS',sum(v[0] for v in vals)/1000,'IDLE_MS',sum(v[1] for v in vals)/1000)
Path('/tmp/gpu_bubble_summary.json').write_text(json.dumps({'base_us':base,'span_us':end-base,'idle_us':idle,'intervals':m,'gaps':[[a,b,pr['name'],ne['name']] for a,b,pr,ne in gaps]}))
